// ================= SETTINGS =================
// Only emails from these addresses get a reply. Everyone else is ignored.
const ALLOWED_SENDERS = ['3bood7amdani@gmail.com'];
// ============================================

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  // Sender address (works with both "Resolved" and "Simple" email formats)
  let from = m.from?.value?.[0]?.address ?? m.from ?? '';
  const match = String(from).match(/[\w.+-]+@[\w.-]+/);
  from = match ? match[0].toLowerCase() : '';
  if (!ALLOWED_SENDERS.includes(from)) continue; // not you -> ignore

  const subject = (m.subject || '(no subject)').trim();
  const cleanSubject = subject.replace(/^((re|fwd?|aw)\s*:\s*)+/i, '').trim() || '(no subject)';

  // Remove the quoted older messages that email apps add under a reply
  let body = String(m.text ?? m.textPlain ?? '');
  const lines = body.split(/\r?\n/);
  const firstQuote = lines.findIndex(l => l.trim().startsWith('>'));
  let kept = firstQuote === -1 ? lines : lines.slice(0, firstQuote);
  // Drop the "On <date> <someone> wrote:" line(s) above the quote
  let joined = kept.join('\n').replace(/\n[^\n]*\bOn\b[^\n]*(\n[^\n]*)?\bwrote:\s*$/i, '');
  joined = joined.replace(/\n[^\n]*(في|بتاريخ)[^\n]*(\n[^\n]*)?كتب:\s*$/, '');
  const question = joined.trim();
  if (!question) continue;

  out.push({
    json: {
      from,
      subject,
      replySubject: `Re: ${cleanSubject}`,
      question,
      // Same sender + same subject = same conversation (memory)
      sessionId: `${from}|${cleanSubject.toLowerCase()}`,
    },
  });
}

return out;
